primaryQuery:
run: order_items extend {
  join_one: ii is inventory_items on inventory_item_id = ii.id
} -> {
  where: status = 'Returned'
  top: 5
  group_by: product_name is ii.product_name
  aggregate: returned_items is count()
  order_by: returned_items desc, product_name asc
}

verifyQuery:
run: inventory_items extend {
  join_one: oi is order_items on id = oi.inventory_item_id
} -> {
  where: oi.status = 'Returned'
  top: 5
  group_by: product_name
  aggregate: returned_items is oi.count()
  order_by: returned_items desc, product_name asc
}
